import{C as n,o,c as i,a2 as t,E as s}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"From 0 to 100 Development Plan","description":"Hearth development plan overview: seven stage modules, each with development steps, increments, deliverables, and exit gates.","frontmatter":{"title":"From 0 to 100 Development Plan","description":"Hearth development plan overview: seven stage modules, each with development steps, increments, deliverables, and exit gates.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/development-plan.md","filePath":"en/delivery/development-plan.md","lastUpdated":1793752688000}'),d={name:"en/delivery/development-plan.md"},u=Object.assign(d,{setup(l){const a=[{no:"S0",meta:"4 increments",title:"Definition & Prototype",text:"Product wedge, real tasks, prototype, contracts, evaluation, and security baseline.",link:"/en/delivery/stage-0"},{no:"S1",meta:"6 increments",title:"Durable Kernel & MVP",text:"Walking skeleton, Codex slice, MVP-1, side-effect safety, and recovery.",link:"/en/delivery/stage-1"},{no:"S2",meta:"6 increments",title:"Personal Operator",text:"Read-only connectors, documents and data, web research, approval-gated writes.",link:"/en/delivery/stage-2"},{no:"S3",meta:"4 increments",title:"Computer Operator",text:"Desktop agentd, observation, takeover, low-risk and high-risk GUI.",link:"/en/delivery/stage-3"},{no:"S4",meta:"5 increments",title:"Proactive Personal Agent",text:"Triggers, proactive inbox, mobile PWA, attention budgets.",link:"/en/delivery/stage-4"},{no:"S5",meta:"4 increments",title:"Memory & Evolution",text:"Memory Core, forgetting, skill candidates, evaluation, promotion, rollback.",link:"/en/delivery/stage-5"},{no:"S6",meta:"6 increments",title:"Multi-device & Operations",text:"Sync, offline queues, revocation, backup migration, long-running operations.",link:"/en/delivery/stage-6"}];return(c,e)=>{const r=n("DocCardGrid");return o(),i("div",null,[e[0]||(e[0]=t('<p class="eyebrow">DEVELOPMENT PLAN</p><h1 id="from-0-to-100-development-plan" tabindex="-1">From 0 to 100 Development Plan <a class="header-anchor" href="#from-0-to-100-development-plan" aria-label="Permalink to &quot;From 0 to 100 Development Plan&quot;">​</a></h1><p class="lead">The product roadmap answers &quot;what counts as complete?&quot; This plan answers &quot;what do we build next?&quot; It is not a weekly Gantt chart; it is seven independently verifiable engineering modules.</p><h2 id="how-to-read-this-plan" tabindex="-1">How to Read This Plan <a class="header-anchor" href="#how-to-read-this-plan" aria-label="Permalink to &quot;How to Read This Plan&quot;">​</a></h2><ul><li>The unit is a vertical increment <code>D0.1 … D6.6</code>, not a week, month, or fixed sprint length.</li><li>Follow dependencies strictly; no increment may deliver only a backend, log, or interface.</li><li>Every increment must let the user complete one concrete task in the browser.</li><li>When a stage gate fails, stay in the current Stage and repair it; do not trade recovery, UI, or verification for progress.</li></ul><h2 id="read-the-master-roadmap-first" tabindex="-1">Read the Master Roadmap First <a class="header-anchor" href="#read-the-master-roadmap-first" aria-label="Permalink to &quot;Read the Master Roadmap First&quot;">​</a></h2><p>The <a href="/hearth-os/en/delivery/roadmap.html">phased product roadmap</a> is the master outline for scope and order. It defines Stage 0–6 goals, scope, exit conditions, and explicit deferrals. This plan expands those stages into engineering steps; when they conflict, the roadmap&#39;s stage gates take precedence.</p><h2 id="seven-development-modules" tabindex="-1">Seven Development Modules <a class="header-anchor" href="#seven-development-modules" aria-label="Permalink to &quot;Seven Development Modules&quot;">​</a></h2>',8)),s(r,{items:a,columns:2}),e[1]||(e[1]=t('<p>Use every module in the same order:</p><ol><li><strong>Prerequisites:</strong> confirm dependencies are stable before moving on.</li><li><strong>Development steps:</strong> build in numbered order, with a concrete outcome for each step.</li><li><strong>Increment breakdown:</strong> confirm the user-visible result and completion evidence for each increment.</li><li><strong>Exit gates:</strong> pass every check before entering the next module; otherwise fix the current one.</li></ol><h2 id="plan-boundaries" tabindex="-1">Plan Boundaries <a class="header-anchor" href="#plan-boundaries" aria-label="Permalink to &quot;Plan Boundaries&quot;">​</a></h2><ul><li><strong>Start:</strong> product definition, a first user, and an empty repository, with no runnable system.</li><li><strong>End:</strong> a Personal Agent OS that can run, migrate, recover, and revoke safely in a real personal environment.</li><li><strong>Unit:</strong> a vertical increment such as D0.1, D1.1, or D2.3, not a week, month, or fixed sprint length.</li><li><strong>Order:</strong> follow dependencies strictly. You may pause, trial, and roll back, but you cannot skip recovery, UI, or verification for speed.</li></ul><h2 id="six-execution-rules" tabindex="-1">Six Execution Rules <a class="header-anchor" href="#six-execution-rules" aria-label="Permalink to &quot;Six Execution Rules&quot;">​</a></h2><ol><li><strong>Vertical slices first.</strong> Every increment includes a user outcome, UI, durable state, real implementation, verification, and recovery.</li><li><strong>The frontend grows with the backend.</strong> Stage 0 has a clickable prototype; Stage 1&#39;s first runnable skeleton includes a real Web task card; every later increment projects into the UI.</li><li><strong>Narrow before wide.</strong> Make one task family dependable before adding a second; prove permissions, idempotency, and receipts on one connector before adding channels.</li><li><strong>Durability before autonomy.</strong> Tasks cannot disappear, effects cannot duplicate, and failures must be visible before proactive loops and high-risk unattended work.</li><li><strong>Safety before real side effects.</strong> Sending, writing, sharing, deleting, and desktop actions require Effect Preview, Mandate, Approval, idempotency, and Receipt drills.</li><li><strong>Evaluation before expansion.</strong> New executors, connectors, models, skills, or automation need representative tasks, baselines, failure samples, and rollback.</li></ol><h2 id="where-the-mvp-fits" tabindex="-1">Where the MVP Fits <a class="header-anchor" href="#where-the-mvp-fits" aria-label="Permalink to &quot;Where the MVP Fits&quot;">​</a></h2><p>MVP-1 is the early Stage 1 exit at D1.3, not a Stage 6 product. It is a real local personal task workbench, initially centered on research/document work. If the first user mainly needs coding tasks, replace the wedge but keep the same vertical structure.</p><table tabindex="0"><thead><tr><th>Dimension</th><th>MVP gate</th></tr></thead><tbody><tr><td>Entry</td><td>Local Web can create tasks, choose a workspace, and reference files or paths</td></tr><tr><td>Task</td><td>One narrow task family end to end: goal, scope, budget, state, and acceptance</td></tr><tr><td>Execution</td><td>Codex runs in an isolated workspace and returns structured results and artifacts</td></tr><tr><td>State</td><td>Queued, running, approval, information-needed, completed, failed, and recoverable states are durable</td></tr><tr><td>UI</td><td>Today/task cards, detail, approval, artifacts, failure, and recovery without CLI knowledge</td></tr><tr><td>Evidence</td><td>Artifacts can be previewed/downloaded with sources, hashes, and verification results</td></tr><tr><td>Side effects</td><td>At least one external action has preview, approval, idempotency, and a drill receipt</td></tr><tr><td>Recovery</td><td>Tasks survive refresh and restart; users can continue, cancel, retry, or move to human handling</td></tr><tr><td>Cost</td><td>Token, model, executor, latency, and manual minutes are recorded</td></tr></tbody></table><h2 id="increment-delivery-template" tabindex="-1">Increment Delivery Template <a class="header-anchor" href="#increment-delivery-template" aria-label="Permalink to &quot;Increment Delivery Template&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Must answer</th></tr></thead><tbody><tr><td>User-visible outcome</td><td>What specific thing can the user now do in the browser?</td></tr><tr><td>Main work</td><td>Which backend, frontend, protocol, executor, and test work is required?</td></tr><tr><td>Completion gate</td><td>What repeatable evidence proves it is complete?</td></tr><tr><td>Failure and recovery</td><td>What does the user see, and how can they cancel, retry, take over, or undo?</td></tr><tr><td>Cost and side effects</td><td>What are the Token, manual-minute, external-action, and receipt results?</td></tr><tr><td>Regression check</td><td>Do the last increment, last stage, and critical safety boundaries still hold?</td></tr></tbody></table><h2 id="five-workstreams-across-every-increment" tabindex="-1">Five Workstreams Across Every Increment <a class="header-anchor" href="#five-workstreams-across-every-increment" aria-label="Permalink to &quot;Five Workstreams Across Every Increment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workstream</th><th>Must be updated in every increment</th></tr></thead><tbody><tr><td>Product and UI</td><td>User story, states, primary action, empty states, failure states, recovery, desktop/mobile layout</td></tr><tr><td>Protocol and projections</td><td>Event, schema, API, Task Pack, Result, projection fields, migration, and contract tests</td></tr><tr><td>Evaluation and safety</td><td>Representative tasks, success/failure samples, permission checks, fault injection, security regression, human acceptance</td></tr><tr><td>Observability and cost</td><td>Trace, executor/model, Token, latency, manual minutes, interruptions, failure classes</td></tr><tr><td>Documentation and migration</td><td>README, ADR, user guidance, security, backup/upgrade, known limits, and data export</td></tr></tbody></table><h2 id="demonstrable-checkpoints" tabindex="-1">Demonstrable Checkpoints <a class="header-anchor" href="#demonstrable-checkpoints" aria-label="Permalink to &quot;Demonstrable Checkpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Checkpoint</th><th>Module</th><th>Demonstrable product state</th></tr></thead><tbody><tr><td>Prototype</td><td>S0</td><td>A clickable end-to-end flow with no real side effects</td></tr><tr><td>Walking skeleton</td><td>S1 · D1.1</td><td>Web + durable tasks + fake executor</td></tr><tr><td>MVP-1</td><td>S1 · D1.3</td><td>A real end-to-end product for one narrow task family</td></tr><tr><td>Stage 1 complete</td><td>S1</td><td>Recoverable kernel, two task families, side-effect safety skeleton</td></tr><tr><td>Personal Operator</td><td>S2</td><td>Email/calendar/document/web/data daily tasks</td></tr><tr><td>Computer Operator</td><td>S3</td><td>GUI observation, takeover, low/high-risk desktop actions</td></tr><tr><td>Proactive agent</td><td>S4</td><td>Proactive loop, mobile PWA, attention budget</td></tr><tr><td>Memory and evolution</td><td>S5</td><td>Correctable memory and rollbackable skills</td></tr><tr><td>Personal Agent OS</td><td>S6</td><td>Multi-device, migration, long-running operation, full audit</td></tr></tbody></table><h2 id="scope-trimming-order" tabindex="-1">Scope Trimming Order <a class="header-anchor" href="#scope-trimming-order" aria-label="Permalink to &quot;Scope Trimming Order&quot;">​</a></h2><p>When resources are constrained, cut scope before foundations: fewer connectors and channels → less proactivity → less native surface → fewer advanced memory types → less multi-device execution → less remote Sandbox → pause skill promotion.</p><p><strong>Never cut:</strong> Web UI and task cards, Event Log and durable state, approval/idempotency/outbox/Receipt, verifiers and failure samples, permissions and secret protection, export/backup/revocation, and user-visible failure reasons and next actions.</p><h2 id="definition-of-complete" tabindex="-1">Definition of Complete <a class="header-anchor" href="#definition-of-complete" aria-label="Permalink to &quot;Definition of Complete&quot;">​</a></h2><p>&quot;100%&quot; does not mean every app and scenario with zero human work. It means every stage exit holds: task coverage is verified; desktop and mobile can view, initiate, approve, take over, and retrieve artifacts; crashes and device switching lose no tasks; high-risk actions are approvable and revocable; memory is explainable, correctable, and forgettable; skills are evaluable and rollbackable; and the system can be installed, migrated, and run long term.</p><h2 id="stage-advancement-checklist" tabindex="-1">Stage Advancement Checklist <a class="header-anchor" href="#stage-advancement-checklist" aria-label="Permalink to &quot;Stage Advancement Checklist&quot;">​</a></h2><ul><li>[ ] Every exit condition has evidence, not a verbal declaration.</li><li>[ ] The latest increment still demonstrates end to end in the browser.</li><li>[ ] Install, start, create task, and recovery work from an empty database.</li><li>[ ] No unresolved high-risk security, duplicate side-effect, or secret-leak issue remains.</li><li>[ ] Every new capability has failure, recovery, and user-visible explanation.</li><li>[ ] Evaluation sets, real-task results, Token/manual minutes, and failure classes are updated.</li><li>[ ] Export, backup, rollback, and known limitations are updated.</li><li>[ ] The next stage does not depend on hidden manual work or developer-machine-only configuration.</li></ul>',22))])}}});export{p as __pageData,u as default};
